<template><main class="hh-page counter-page"><router-link :to="`/referencias/${referenceId}`" class="hh-back-link d-inline-flex align-items-center mb-3"><i class="ph ph-arrow-left me-1"></i>Volver a la referencia</router-link><section class="counter-hero"><div><span>CONTINUIDAD ASISTENCIAL</span><h1>{{existing?'Contrarreferencia':'Crear contrarreferencia'}}</h1><p>Documente el resultado de la atención y el plan posterior del paciente.</p></div><i class="ph ph-arrow-bend-up-left"></i></section><div v-if="loading" class="text-center py-5"><span class="spinner-border text-primary"></span></div><div v-else-if="error" class="alert alert-danger mt-3">{{error}}</div><form v-else class="counter-form mt-4" @submit.prevent="save"><header><div><small>{{existing?'REGISTRO EXISTENTE':'NUEVO REGISTRO'}}</small><h2>Resumen clínico de egreso</h2></div><span v-if="existing" class="badge bg-success-subtle text-success">Contrarreferida</span></header><div class="form-body"><div class="row g-3"><div class="col-md-6"><label class="form-label">Diagnóstico final *</label><select v-model="form.diagnostico_final_codigo" class="form-select" required><option value="" disabled>Seleccione CIE-10</option><option v-for="item in diagnoses" :key="id(item)" :value="id(item)">{{item.codigo?`${item.codigo} — `:''}}{{name(item)}}</option></select></div><div class="col-md-6"><label class="form-label">Condición de egreso *</label><select v-model="form.condicion_egreso" class="form-select" required><option value="" disabled>Seleccione</option><option v-for="item in conditions" :key="id(item)" :value="id(item)">{{name(item)}}</option></select></div><div v-for="field in textFields" :key="field.key" :class="field.wide?'col-12':'col-md-6'"><label class="form-label">{{field.label}} <span v-if="field.required">*</span></label><textarea v-model.trim="form[field.key]" class="form-control" rows="3" :required="field.required"></textarea></div><div class="col-md-6"><label class="form-label">Médico que contrarrefiere *</label><select v-model="form.medico_contrarefiere_id" class="form-select" required><option value="" disabled>Seleccione</option><option v-for="item in doctors" :key="id(item)" :value="id(item)">{{name(item)}}</option></select></div><div class="col-md-6"><label class="form-label">Cargo médico</label><input v-model.trim="form.cargo_medico" class="form-control"></div></div><label class="follow-up mt-3"><span><strong>Requiere seguimiento</strong><small>Activa la programación del próximo control.</small></span><input v-model="form.requiere_seguimiento" type="checkbox" class="form-check-input"></label><div v-if="form.requiere_seguimiento" class="row g-3 mt-0"><div class="col-md-4"><label class="form-label">Próximo control *</label><input v-model="form.fecha_proximo_control" type="date" :min="tomorrow" class="form-control" required></div><div class="col-md-4"><label class="form-label">Frecuencia</label><input v-model.trim="form.frecuencia_seguimiento" class="form-control"></div><div class="col-md-4"><label class="form-label">Especialidad</label><input v-model.trim="form.especialidad_seguimiento" class="form-control"></div></div></div><footer><router-link :to="`/referencias/${referenceId}`" class="btn btn-outline-secondary">Cancelar</router-link><button class="btn btn-primary" :disabled="saving"><span v-if="saving" class="spinner-border spinner-border-sm me-2"></span>{{existing?'Guardar cambios':'Crear contrarreferencia'}}</button></footer></form></main></template>
<script setup>import{onMounted,reactive,ref}from'vue';import{useRoute}from'vue-router';import{obtenerMensajeError}from'@/services/api';import{actualizarContrareferencia,consultarCatalogosReferencia,consultarContrareferencia,crearContrareferencia,listarDiagnosticos,listarMedicosReceptores}from'@/services/referencias';const route=useRoute(),referenceId=Number(route.params.id),loading=ref(true),saving=ref(false),error=ref(''),existing=ref(null),diagnoses=ref([]),conditions=ref([]),doctors=ref([]),tomorrow=new Date(Date.now()+86400000).toISOString().slice(0,10),form=reactive({diagnostico_final_codigo:'',resumen_atencion:'',evolucion_paciente:'',tratamiento_brindado:'',plan_manejo_ambulatorio:'',hallazgos_relevantes:'',procedimientos_realizados:'',examenes_realizados:'',medicamentos_administrados:'',indicaciones_especiales:'',signos_alarma:'',condicion_egreso:'',requiere_seguimiento:false,frecuencia_seguimiento:'',fecha_proximo_control:'',especialidad_seguimiento:'',medico_contrarefiere_id:'',cargo_medico:''}),textFields=[{key:'resumen_atencion',label:'Resumen de la atención',required:true,wide:true},{key:'evolucion_paciente',label:'Evolución del paciente',required:true},{key:'tratamiento_brindado',label:'Tratamiento brindado',required:true},{key:'plan_manejo_ambulatorio',label:'Plan de manejo ambulatorio',required:true,wide:true},{key:'hallazgos_relevantes',label:'Hallazgos relevantes'},{key:'procedimientos_realizados',label:'Procedimientos realizados'},{key:'examenes_realizados',label:'Exámenes realizados'},{key:'medicamentos_administrados',label:'Medicamentos administrados'},{key:'indicaciones_especiales',label:'Indicaciones especiales'},{key:'signos_alarma',label:'Signos de alarma',wide:true}],array=v=>Array.isArray(v)?v:Array.isArray(v?.data)?v.data:[],id=x=>x.id??x.id_usuario,name=x=>x.nombre??x.name??x.descripcion;async function save(){saving.value=true;error.value='';try{const payload={...form,diagnostico_final_codigo:Number(form.diagnostico_final_codigo),condicion_egreso:Number(form.condicion_egreso),medico_contrarefiere_id:Number(form.medico_contrarefiere_id),fecha_proximo_control:form.requiere_seguimiento?form.fecha_proximo_control:null};existing.value?await actualizarContrareferencia(existing.value.id,payload):await crearContrareferencia(referenceId,payload);await load()}catch(e){error.value=obtenerMensajeError(e)}finally{saving.value=false}}async function load(){loading.value=true;const rs=await Promise.allSettled([consultarContrareferencia(referenceId),listarDiagnosticos(),listarMedicosReceptores(),consultarCatalogosReferencia()]);if(rs[0].status==='fulfilled'){existing.value=rs[0].value?.data||rs[0].value;Object.keys(form).forEach(k=>{if(existing.value[k]!==undefined&&existing.value[k]!==null)form[k]=existing.value[k]});form.diagnostico_final_codigo=existing.value.diagnostico_final?.id||existing.value.diagnostico_final_codigo||'';form.condicion_egreso=existing.value.condicion_egreso?.id||existing.value.condicion_egreso_id||existing.value.condicion_egreso||''}else if(rs[0].reason?.status!==404)error.value=obtenerMensajeError(rs[0].reason);if(rs[1].status==='fulfilled')diagnoses.value=array(rs[1].value);if(rs[2].status==='fulfilled')doctors.value=array(rs[2].value);if(rs[3].status==='fulfilled'){const s=rs[3].value?.data||rs[3].value;conditions.value=s.condiciones_egreso||[]}loading.value=false}onMounted(load)</script>
<style scoped>.counter-hero{display:flex;align-items:center;justify-content:space-between;padding:1.3rem 1.5rem;border-radius:1rem;background:linear-gradient(120deg,#0b5688,#148fbd);color:#fff}.counter-hero span{font-size:.6rem;font-weight:800;letter-spacing:.08em}.counter-hero h1{margin:.2rem 0;font-size:1.45rem}.counter-hero p{margin:0;opacity:.8}.counter-hero>i{font-size:2.4rem;opacity:.35}.counter-form{overflow:hidden;border:1px solid #dfe7ee;border-radius:1rem;background:#fff;box-shadow:0 10px 30px rgba(24,64,96,.07)}.counter-form>header{display:flex;align-items:center;justify-content:space-between;padding:1rem 1.25rem;border-bottom:1px solid #e4eaf0;background:#fbfcfe}.counter-form header small{color:var(--bs-primary);font-size:.58rem;font-weight:800}.counter-form h2{margin:.1rem 0;font-size:1.05rem}.form-body{padding:1.25rem}.counter-form footer{display:flex;justify-content:flex-end;gap:.6rem;padding:1rem 1.25rem;border-top:1px solid #e4eaf0}.follow-up{display:flex;align-items:center;justify-content:space-between;padding:.8rem;border:1px solid #dfe7ee;border-radius:.7rem;background:#f8fafc}.follow-up strong,.follow-up small{display:block}.follow-up strong{font-size:.77rem}.follow-up small{color:#7b8999;font-size:.65rem}</style>
